// SPDX-License-Identifier: MIT
// -------------------
// Aggregator Version: 1.0
// -------------------
pragma solidity 0.8.30;



// ERC20 Interface
interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

// library for transfer helper functions
library TransferHelper {
    function safeApprove(address token, address to, uint value) internal {
        // bytes4(keccak256(bytes('approve(address,uint256)')));
        (bool success, bytes memory data) = token.call(abi.encodeWithSelector(0x095ea7b3, to, value));
        require(success && (data.length == 0 || abi.decode(data, (bool))), 'TransferHelper: APPROVE_FAILED');
    }

    function safeTransfer(address token, address to, uint value) internal {
        // bytes4(keccak256(bytes('transfer(address,uint256)')));
        (bool success, bytes memory data) = token.call(abi.encodeWithSelector(0xa9059cbb, to, value));
        require(success && (data.length == 0 || abi.decode(data, (bool))), 'TransferHelper: TRANSFER_FAILED');
    }

    function safeTransferFrom(address token, address from, address to, uint value) internal {
        // bytes4(keccak256(bytes('transferFrom(address,address,uint256)')));
        (bool success, bytes memory data) = token.call(abi.encodeWithSelector(0x23b872dd, from, to, value));
        require(success && (data.length == 0 || abi.decode(data, (bool))), 'TransferHelper: TRANSFER_FROM_FAILED');
    }

    function safeTransferETH(address to, uint value) internal {
        (bool success,) = to.call{value:value}(new bytes(0));
        require(success, 'TransferHelper: ETH_TRANSFER_FAILED');
    }
}

// THORChain Router Interface
interface iROUTER {
    function depositWithExpiry(address payable to, address asset, uint256 amount, string calldata memo, uint256 expiration) external payable;
}

// Sushi Interface
interface iSWAPROUTER {
    function swapExactTokensForETH(uint256 amountIn, uint256 amountOutMin, address[] calldata path, address to, uint256 deadline) external;
    function swapExactETHForTokens(uint amountOutMin, address[] calldata path, address to, uint deadline) external payable;
    function swapExactTokensForTokens(uint amountIn, uint amountOutMin, address[] calldata path, address to, uint deadline) external returns (uint[] memory amounts);
}

// THORChain_Aggregator is permissionless
contract THORChain_Aggregator {

    uint256 private constant _NOT_ENTERED = 1;
    uint256 private constant _ENTERED = 2;
    uint256 private _status;

    address private ETH = address(0);
    iSWAPROUTER public swapRouter;

    modifier nonReentrant() {
        require(_status != _ENTERED, "ReentrancyGuard: reentrant call");
        _status = _ENTERED;
        _;
        _status = _NOT_ENTERED;
    }

    constructor(address _swapRouter) {
        _status = _NOT_ENTERED;
        swapRouter = iSWAPROUTER(_swapRouter);
    }

    receive() external payable {}

     //############################## IN ##############################

    function swapIn(
        address tcVault, 
        address tcRouter, 
        string calldata tcMemo, 
        address fromToken,
        uint amount, 
        uint amountOutMin, 
        uint256 deadline
        ) public nonReentrant {
        return _swapIn(tcVault, tcRouter, tcMemo, fromToken, ETH, amount, amountOutMin, deadline);
    }

    function swapInV2(
        address tcVault, 
        address tcRouter, 
        string calldata tcMemo, 
        address fromToken,
        address toToken,
        uint amount, 
        uint amountOutMin, 
        uint256 deadline
        ) public payable nonReentrant {
        // Check if fromToken is ETH (special case - direct ETH input)
        if(fromToken == ETH) {
            require(msg.value > 0, "TC:eth amount mismatch");
            require(amount == msg.value, "TC:eth amount mismatch");
            _swapInETH(tcVault, tcRouter, tcMemo, toToken, amountOutMin, deadline);
        } else {
            _swapIn(tcVault, tcRouter, tcMemo, fromToken, toToken, amount, amountOutMin, deadline);
        }
    }

    function _swapInETH(
        address tcVault, 
        address tcRouter, 
        string calldata tcMemo, 
        address toToken, 
        uint amountOutMin, 
        uint256 deadline
        ) internal {
        uint256 _safeAmount = msg.value; // Use the sent ETH

        // Handle ETH to Token swap
        if(toToken != ETH) {
            // ETH to Token swap
            address[] memory path = new address[](2);
            path[0] = ETH; path[1] = toToken;
            swapRouter.swapExactETHForTokens{value: _safeAmount}(amountOutMin, path, address(this), deadline);

            // Get the swapped token balance
            _safeAmount = IERC20(toToken).balanceOf(address(this));

            // Approve router to spend the tokens
            TransferHelper.safeApprove(toToken, tcRouter, _safeAmount);

            // Deposit tokens to THORChain via router
            iROUTER(tcRouter).depositWithExpiry(payable(tcVault), toToken, _safeAmount, tcMemo, deadline);
        } else {
            // ETH to ETH (just forward)
            iROUTER(tcRouter).depositWithExpiry{value:_safeAmount}(payable(tcVault), ETH, _safeAmount, tcMemo, deadline);
        }
    }

    function _swapIn(
        address tcVault, 
        address tcRouter, 
        string calldata tcMemo, 
        address fromToken,
        address toToken,
        uint amount, 
        uint amountOutMin, 
        uint256 deadline
        ) internal {
        // Transfer asset from user to this contract
        TransferHelper.safeTransferFrom(fromToken, msg.sender, address(this), amount);
        uint256 _safeAmount = amount; // The amount successfully transferred to this contract
        TransferHelper.safeApprove(fromToken, address(swapRouter), _safeAmount);

        // Handle different swap types based on toToken
        if (toToken == ETH) {
            // Token to ETH swap
            address[] memory path = new address[](2);
            path[0] = fromToken; path[1] = ETH;
            swapRouter.swapExactTokensForETH(_safeAmount, amountOutMin, path, address(this), deadline);
            _safeAmount = address(this).balance; // Update _safeAmount to current ETH balance

            // Deposit ETH to THORChain via router
            iROUTER(tcRouter).depositWithExpiry{value:_safeAmount}(payable(tcVault), ETH, _safeAmount, tcMemo, deadline);
        } else {
            // Token to Token swap
            address[] memory path = new address[](2);
            path[0] = fromToken; path[1] = toToken;
            swapRouter.swapExactTokensForTokens(_safeAmount, amountOutMin, path, address(this), deadline);

            // Get the swapped token balance
            _safeAmount = IERC20(toToken).balanceOf(address(this));

            // Approve router to spend the tokens
            TransferHelper.safeApprove(toToken, tcRouter, _safeAmount);

            // Deposit tokens to THORChain via router
            iROUTER(tcRouter).depositWithExpiry(payable(tcVault), toToken, _safeAmount, tcMemo, deadline);
        }
    }

    //############################## OUT ##############################

    function swapOut(address token, address to, uint256 amountOutMin) external payable nonReentrant {
        _swapOut(token, to, amountOutMin);
    }

    // V2 version of swapOut that handles both ETH and token inputs
    function swapOutV2(
        address fromAsset,
        uint256 fromAmount,
        address toAsset,
        address recipient,
        uint256 amountOutMin,
        bytes calldata,  // payload (unused)
        string calldata  // originAddress (unused)
    ) public payable nonReentrant {

        // If we're receiving ETH, call swapOut
        if (fromAsset == ETH) {
            _swapOut(toAsset, recipient, amountOutMin);
        } else {
            // First pull tokens from the sender (router) to this contract
            TransferHelper.safeTransferFrom(fromAsset, msg.sender, address(this), fromAmount);
            _swapOutV2(fromAsset, toAsset, recipient, amountOutMin);
        }
    }

    function _swapOut(address token, address to, uint256 amountOutMin) internal {
        // If the target token is ETH (address(0)), just forward the ETH
        if (token == ETH) {
            (bool success, ) = to.call{value: msg.value}("");
            require(success, "ETH transfer failed");
            return;
        }

        // Otherwise swap ETH to the requested token
        address[] memory path = new address[](2);
        path[0] = ETH; path[1] = token;
        swapRouter.swapExactETHForTokens{value: msg.value}(amountOutMin, path, to, type(uint).max);
    }

    function _swapOutV2(address fromAsset, address toAsset, address recipient, uint256 amountOutMin) internal {
        uint balance = IERC20(fromAsset).balanceOf(address(this));
        TransferHelper.safeApprove(fromAsset, address(swapRouter), balance);
        // If destination is not ETH, do token to token swap
        if (toAsset != ETH) {
            // Create path from input token to output token
            address[] memory path = new address[](2);
            path[0] = fromAsset; path[1] = toAsset;
            // Execute the swap
            swapRouter.swapExactTokensForTokens(
                balance, // Use our balance as the input amount
                amountOutMin,
                path,
                recipient,
                type(uint).max
            );

        } else {
            address[] memory path = new address[](2);
            path[0] = fromAsset; path[1] = ETH;
            swapRouter.swapExactTokensForETH(
                balance,
                amountOutMin,
                path,
                recipient,
                type(uint).max
            );
        }
    }
}

contracts/THORChain_AggregatorUniswap.so.content:
// SPDX-License-Identifier: MIT
// -------------------
// Aggregator Version: 1.0 - Uniswap V3
// -------------------
pragma solidity 0.8.30;

// ERC20 Interface
interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

// WETH9 Interface
interface IWETH9 {
    function deposit() external payable;
    function withdraw(uint256) external;
}

// library for transfer helper functions
library TransferHelper {
    function safeApprove(address token, address to, uint value) internal {
        // bytes4(keccak256(bytes('approve(address,uint256)')));
        (bool success, bytes memory data) = token.call(abi.encodeWithSelector(0x095ea7b3, to, value));
        require(success && (data.length == 0 || abi.decode(data, (bool))), 'TransferHelper: APPROVE_FAILED');
    }

    function safeTransfer(address token, address to, uint value) internal {
        // bytes4(keccak256(bytes('transfer(address,uint256)')));
        (bool success, bytes memory data) = token.call(abi.encodeWithSelector(0xa9059cbb, to, value));
        require(success && (data.length == 0 || abi.decode(data, (bool))), 'TransferHelper: TRANSFER_FAILED');
    }

    function safeTransferFrom(address token, address from, address to, uint value) internal {
        // bytes4(keccak256(bytes('transferFrom(address,address,uint256)')));
        (bool success, bytes memory data) = token.call(abi.encodeWithSelector(0x23b872dd, from, to, value));
        require(success && (data.length == 0 || abi.decode(data, (bool))), 'TransferHelper: TRANSFER_FROM_FAILED');
    }

    function safeTransferETH(address to, uint value) internal {
        (bool success,) = to.call{value:value}(new bytes(0));
        require(success, 'TransferHelper: ETH_TRANSFER_FAILED');
    }
}

// THORChain Router Interface
interface iROUTER {
    function depositWithExpiry(address payable to, address asset, uint256 amount, string calldata memo, uint256 expiration) external payable;
}

// Uniswap V3 SwapRouter Interface
interface ISwapRouter {
    struct ExactInputSingleParams {
        address tokenIn;
        address tokenOut;
        uint24 fee;
        address recipient;
        uint256 deadline;
        uint256 amountIn;
        uint256 amountOutMinimum;
        uint160 sqrtPriceLimitX96;
    }

    /// @notice Swaps `amountIn` of one token for as much as possible of another token
    /// @param params The parameters necessary for the swap, encoded as `ExactInputSingleParams` in calldata
    /// @return amountOut The amount of the received token
    function exactInputSingle(ExactInputSingleParams calldata params) external payable returns (uint256 amountOut);
}

// Uniswap V3 Quoter Interface
interface IQuoter {
    /// @notice Returns the amount out received for a given exact input swap without executing the swap
    function quoteExactInput(bytes memory path, uint256 amountIn) external returns (uint256 amountOut);

    /// @notice Returns the amount out received for a given exact input but for a single swap
    function quoteExactInputSingle(
        address tokenIn,
        address tokenOut,
        uint24 fee,
        uint256 amountIn,
        uint160 sqrtPriceLimitX96
    ) external returns (uint256 amountOut);
}

// THORChain_AggregatorUniswap is permissionless
contract THORChain_AggregatorUniswap {

    uint256 private constant _NOT_ENTERED = 1;
    uint256 private constant _ENTERED = 2;
    uint256 private _status;

    address private constant ETH = address(0);
    address public WETH9;
    address public owner;

    // Uniswap V3 Contracts
    ISwapRouter public swapRouter;
    IQuoter public quoter;

    // Dynamic fee tiers array for Uniswap V3
    uint24[] public feeTiers;

    // Events
    event Swapped(address indexed fromToken, address indexed toToken, uint256 amountIn, uint256 amountOut);
    event Deposited(address indexed tcVault, address indexed asset, uint256 amount, string memo);
    event SwapFailed(address indexed fromToken, address indexed toToken, uint256 amount);
    event TransferFailed(address indexed token, address indexed to, uint256 amount);
    event EthReceived(uint256 amount);
    event RefundedEth(address indexed to, uint256 amount);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event FeeTiersUpdated(uint24[] feeTiers);

    modifier nonReentrant() {
        require(_status != _ENTERED, "ReentrancyGuard: reentrant call");
        _status = _ENTERED;
        _;
        _status = _NOT_ENTERED;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    constructor() {
        _status = _NOT_ENTERED;
        owner = tx.origin;
        // Initialize fee tiers to common Uniswap V3 values
        feeTiers.push(3000);  // 0.3% (most common)
        feeTiers.push(500);   // 0.05%
        feeTiers.push(10000); // 1%
    }

    function setUniswapAddresses(address _swapRouter, address _quoter, address _weth) external onlyOwner {
        swapRouter = ISwapRouter(_swapRouter);
        quoter = IQuoter(_quoter);
        WETH9 = _weth;
    }

    function setFeeTiers(uint24[] calldata _feeTiers) external onlyOwner {
        require(_feeTiers.length > 0 && _feeTiers.length <= 10, "Invalid fee tiers length");
        for (uint i = 0; i < _feeTiers.length; i++) {
            require(_feeTiers[i] > 0, "Fee tier must be greater than 0");
        }
        delete feeTiers;
        for (uint i = 0; i < _feeTiers.length; i++) {
            feeTiers.push(_feeTiers[i]);
        }
        emit FeeTiersUpdated(_feeTiers);
    }

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "New owner cannot be zero address");
        address oldOwner = owner;
        owner = newOwner;
        emit OwnershipTransferred(oldOwner, newOwner);
    }

    receive() external payable {
        emit EthReceived(msg.value);
    }

    // Helper function to validate ETH usage with ERC20 transactions
    function _validateEthUsage(address token) internal view {
        if(token != ETH && msg.value > 0) {
            revert("ETH sent with ERC20 operation");
        }
    }

    /**
     * @dev Gas-efficient fee discovery that tries fee tiers in order of likelihood
     * @param tokenIn Input token address
     * @param tokenOut Output token address  
     * @param amountIn Input amount
     * @return bestFee Best fee tier found (0 if none work)
     */
    function _findBestFee(address tokenIn, address tokenOut, uint256 amountIn) internal returns (uint24 bestFee) {
        // Try all configured fee tiers
        for (uint256 i = 0; i < feeTiers.length;) {
            try quoter.quoteExactInputSingle(tokenIn, tokenOut, feeTiers[i], amountIn, 0) returns (uint256 quote) {
                if (quote > 0) {
                    return feeTiers[i];
                }
            } catch {
                // Continue to next fee tier
            }
            unchecked { ++i; }
        }

        return 0; // No working fee tier found
    }

    /**
     * @dev Gas-efficient swap execution with fee discovery
     * @param tokenIn Input token address
     * @param tokenOut Output token address
     * @param amountIn Input amount
     * @param amountOutMin Minimum output amount
     * @param deadline Transaction deadline
     * @return amountOut Actual output amount
     */
    function _executeSwapWithFeeDiscovery(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 amountOutMin,
        uint256 deadline
    ) internal returns (uint256 amountOut) {
        // Find best fee tier
        uint24 bestFee = _findBestFee(tokenIn, tokenOut, amountIn);

        // Use first fee tier as fallback if no optimal fee found
        if (bestFee == 0 && feeTiers.length > 0) {
            bestFee = feeTiers[0];
        }

        // Execute swap with discovered fee
        try swapRouter.exactInputSingle(ISwapRouter.ExactInputSingleParams({
            tokenIn: tokenIn,
            tokenOut: tokenOut,
            fee: bestFee,
            recipient: address(this),
            deadline: deadline,
            amountIn: amountIn,
            amountOutMinimum: amountOutMin,
            sqrtPriceLimitX96: 0
        })) returns (uint256 _amountOut) {
            return _amountOut;
        } catch {
            revert("Swap failed");
        }
    }

    //############################## IN ##############################


    function swapIn(
        address tcVault, 
        address tcRouter, 
        string calldata tcMemo, 
        address fromToken,
        address toToken,
        uint amount, 
        uint amountOutMin, 
        uint256 deadline
        ) public payable nonReentrant {
        // Check if fromToken is ETH (special case - direct ETH input)
        if(fromToken == ETH) {
            require(msg.value > 0, "TC:eth amount mismatch");
            require(amount == msg.value, "TC:eth amount mismatch");
            _swapInETH(tcVault, tcRouter, tcMemo, toToken, amountOutMin, deadline);
        } else {
            // Validate no ETH is sent with token operations
            _validateEthUsage(fromToken);
            _swapIn(tcVault, tcRouter, tcMemo, fromToken, toToken, amount, amountOutMin, deadline);
        }
    }

    function _swapInETH(
        address tcVault, 
        address tcRouter, 
        string calldata tcMemo, 
        address toToken, 
        uint amountOutMin, 
        uint256 deadline
        ) internal {
        uint256 _safeAmount = msg.value;

        // If target token is not ETH, perform ETH to Token swap
        if (toToken != ETH) {
            // Wrap ETH to WETH first (required for Uniswap V3)
            IWETH9(WETH9).deposit{value: _safeAmount}();

            // Approve the router to spend WETH
            TransferHelper.safeApprove(WETH9, address(swapRouter), _safeAmount);

            // Find optimal fee tier and execute swap
            _safeAmount = _executeSwapWithFeeDiscovery(WETH9, toToken, _safeAmount, amountOutMin, deadline);
            emit Swapped(ETH, toToken, msg.value, _safeAmount);

            // Approve router to spend the target token
            TransferHelper.safeApprove(toToken, tcRouter, _safeAmount);

            // Deposit tokens to THORChain via router
            iROUTER(tcRouter).depositWithExpiry(payable(tcVault), toToken, _safeAmount, tcMemo, deadline);
            emit Deposited(tcVault, toToken, _safeAmount, tcMemo);
        } else {
            // ETH to ETH (just forward)
            iROUTER(tcRouter).depositWithExpiry{value:_safeAmount}(payable(tcVault), ETH, _safeAmount, tcMemo, deadline);
            emit Deposited(tcVault, ETH, _safeAmount, tcMemo);
        }
    }

    function _swapIn(
        address tcVault, 
        address tcRouter, 
        string calldata tcMemo, 
        address fromToken,
        address toToken,
        uint amount, 
        uint amountOutMin, 
        uint256 deadline
        ) internal {
        // Transfer tokens from sender to this contract
        uint256 _safeAmount = amount;
        TransferHelper.safeTransferFrom(fromToken, msg.sender, address(this), _safeAmount);

        // Approve router to spend the fromToken
        TransferHelper.safeApprove(fromToken, address(swapRouter), _safeAmount);

        // Handle different swap types based on toToken
        if (toToken == ETH) {
            // Token to ETH swap - swap to WETH first then unwrap
            uint256 amountOut = _executeSwapWithFeeDiscovery(fromToken, WETH9, _safeAmount, amountOutMin, deadline);

            // Unwrap WETH to ETH
            IWETH9(WETH9).withdraw(amountOut);
            uint256 ethAmount = address(this).balance;

            // Deposit ETH to THORChain via router
            iROUTER(tcRouter).depositWithExpiry{value: ethAmount}(payable(tcVault), ETH, ethAmount, tcMemo, deadline);
            emit Swapped(fromToken, ETH, amount, ethAmount);
            emit Deposited(tcVault, ETH, ethAmount, tcMemo);
        } else {
            // Token to Token swap
            uint256 amountOut = _executeSwapWithFeeDiscovery(fromToken, toToken, _safeAmount, amountOutMin, deadline);

            // Approve router to spend the output tokens
            TransferHelper.safeApprove(toToken, tcRouter, amountOut);

            // Deposit tokens to THORChain via router
            iROUTER(tcRouter).depositWithExpiry(payable(tcVault), toToken, amountOut, tcMemo, deadline);
            emit Swapped(fromToken, toToken, amount, amountOut);
            emit Deposited(tcVault, toToken, amountOut, tcMemo);
        }
    }

    //############################## QUOTE ##############################

    /// @notice Get quote for swap from one token to another
    /// @param fromToken Address of the input token
    /// @param toToken Address of the output token
    /// @param amount Amount of input token
    /// @return amountOut The amount of output token that would be received
    function quoteSwapIn(
        address fromToken,
        address toToken, 
        uint256 amount
    ) public returns (uint256 amountOut) {
        // For ETH input, use WETH address
        address actualFromToken = fromToken == ETH ? WETH9 : fromToken;
        address actualToToken = toToken == ETH ? WETH9 : toToken;

        // Create path for single hop swap (fromToken -> toToken with first fee tier)
        uint24 quoteFee = feeTiers.length > 0 ? feeTiers[0] : 3000; // fallback to 0.3%
        bytes memory path = abi.encodePacked(actualFromToken, quoteFee, actualToToken);

        return quoter.quoteExactInput(path, amount);
    }

    //############################## OUT ##############################

    function swapOut(address token, address to, uint256 amountOutMin) external payable nonReentrant {
        _swapOut(token, to, amountOutMin);
    }

    // V2 version of swapOut that handles both ETH and token inputs
    function swapOutV2(
        address fromAsset,
        uint256 fromAmount,
        address toAsset,
        address recipient,
        uint256 amountOutMin,
        bytes calldata,  // payload (unused)
        string calldata  // originAddress (unused)
    ) public payable nonReentrant {

        // If we're receiving ETH, call swapOut
        if (fromAsset == ETH) {
            // Validate ETH amount
            require(msg.value > 0, "TC:eth amount mismatch");
            require(msg.value == fromAmount, "TC:eth amount mismatch");
            _swapOut(toAsset, recipient, amountOutMin);
        } else {
            // Validate no ETH is sent with token operations
            _validateEthUsage(fromAsset);
            // First pull tokens from the sender (router) to this contract
            TransferHelper.safeTransferFrom(fromAsset, msg.sender, address(this), fromAmount);
            _swapOutV2(fromAsset, toAsset, recipient, amountOutMin);
        }
    }

    function _swapOut(address token, address to, uint256 amountOutMin) internal {
        // If the target token is ETH (address(0)), just forward the ETH
        if (token == ETH) {
            (bool success, ) = to.call{value: msg.value}("");
            if (!success) {
                emit TransferFailed(ETH, to, msg.value);
                revert("ETH transfer failed");
            }
            return;
        }

        // Otherwise swap ETH to the requested token
        // First wrap ETH to WETH (required for Uniswap V3)
        IWETH9(WETH9).deposit{value: msg.value}();

        // Approve the router to spend WETH
        TransferHelper.safeApprove(WETH9, address(swapRouter), msg.value);

        // Find best fee for WETH -> token swap
        uint24 swapFee = _findBestFee(WETH9, token, msg.value);
        if (swapFee == 0 && feeTiers.length > 0) {
            swapFee = feeTiers[0]; // fallback to first fee tier
        }

        // Swap WETH for the target token
        ISwapRouter.ExactInputSingleParams memory params = ISwapRouter.ExactInputSingleParams({
            tokenIn: WETH9,
            tokenOut: token,
            fee: swapFee,
            recipient: to,
            deadline: type(uint256).max,
            amountIn: msg.value,
            amountOutMinimum: amountOutMin,
            sqrtPriceLimitX96: 0
        });

        try swapRouter.exactInputSingle(params) returns (uint256 amountOut) {
            emit Swapped(ETH, token, msg.value, amountOut);
        } catch {
            emit SwapFailed(ETH, token, msg.value);
            revert("Swap to token failed");
        }
    }

    function _swapOutV2(address fromAsset, address toAsset, address recipient, uint256 amountOutMin) internal {
        uint256 balance = IERC20(fromAsset).balanceOf(address(this));
        TransferHelper.safeApprove(fromAsset, address(swapRouter), balance);

        // If destination is not ETH, do token to token swap
        if (toAsset != ETH) {
            // Find best fee for token -> token swap
            uint24 swapFee = _findBestFee(fromAsset, toAsset, balance);
            if (swapFee == 0 && feeTiers.length > 0) {
                swapFee = feeTiers[0]; // fallback to first fee tier
            }

            // Create params for token to token swap
            ISwapRouter.ExactInputSingleParams memory params = ISwapRouter.ExactInputSingleParams({
                tokenIn: fromAsset,
                tokenOut: toAsset,
                fee: swapFee,
                recipient: recipient,
                deadline: type(uint256).max,
                amountIn: balance,
                amountOutMinimum: amountOutMin,
                sqrtPriceLimitX96: 0
            });

            try swapRouter.exactInputSingle(params) returns (uint256 amountOut) {
                emit Swapped(fromAsset, toAsset, balance, amountOut);
            } catch {
                emit SwapFailed(fromAsset, toAsset, balance);
                revert("Token to token swap failed");
            }
        } else {
            // Token to ETH swap requires WETH unwrapping
            // Find best fee for token -> WETH swap
            uint24 swapFee = _findBestFee(fromAsset, WETH9, balance);
            if (swapFee == 0 && feeTiers.length > 0) {
                swapFee = feeTiers[0]; // fallback to first fee tier
            }

            ISwapRouter.ExactInputSingleParams memory params = ISwapRouter.ExactInputSingleParams({
                tokenIn: fromAsset,
                tokenOut: WETH9,
                fee: swapFee,
                recipient: address(this), // First receive WETH here
                deadline: type(uint256).max,
                amountIn: balance,
                amountOutMinimum: amountOutMin,
                sqrtPriceLimitX96: 0
            });

            try swapRouter.exactInputSingle(params) returns (uint256 amountOut) {
                // Unwrap WETH to ETH and send to recipient
                IWETH9(WETH9).withdraw(amountOut);

                // Forward ETH to recipient
                (bool success, ) = recipient.call{value: amountOut}("");
                if (!success) {
                    emit TransferFailed(ETH, recipient, amountOut);
                    revert("ETH transfer failed");
                }

                emit Swapped(fromAsset, ETH, balance, amountOut);
            } catch {
                emit SwapFailed(fromAsset, ETH, balance);
                revert("Token to ETH swap failed");
            }
        }
    }
}

contracts/THORChain_RouterV6.sol.content:
// SPDX-License-Identifier: MIT
// -------------------
// Router Version: 6.0
// -------------------
pragma solidity 0.8.30;

// ERC20 Interface
interface iERC20 {
    function balanceOf(address) external view returns (uint256);
}
// ROUTER Interface
interface iROUTER {
    function depositWithExpiry(address, address, uint, string calldata, uint) external;
}

// THORChain_Router
contract THORChain_Router {

    bytes4 private constant TRANSFER_SIG = 0xa9059cbb; // transfer(address,uint256)
    bytes4 private constant TRANSFER_FROM_SIG = 0x23b872dd; // transferFrom(address,address,uint256)
    bytes4 private constant APPROVE_SIG = 0x095ea7b3; // approve(address,uint256)
    bytes4 private constant SWAP_OUT_SIG = 0x48c314f4; // swapOut(address,address,uint256)
    bytes4 private constant SWAP_OUT_V2_SIG = 0x486e77ba; // swapOutV2(address,uint256,address,address,uint256,bytes,string)

    bool private constant _NOT_ENTERED = false;
    bool private constant _ENTERED = true;
    address private constant ETH_ASSET = address(0);
    bool private transient _status;  // initialised false

    struct Params {
        address payable target;
        address fromAsset;
        uint256 fromAmount;
        address toAsset;
        address recipient;
        uint256 amountOutMin;
        string memo;
        bytes payload;
        string originAddress;
      }

    // Emitted for deposits
    event Deposit(address indexed to, address indexed asset, uint amount, string memo);

    // Emitted for outgoing transfers
    event TransferOut(address indexed vault, address indexed to, address asset, uint amount, string memo);

    // Emitted for outgoing transferAndCalls
    event TransferOutAndCall(address indexed vault, address target, uint amount, address finalAsset, address to, uint256 amountOutMin, string memo);
    event TransferOutAndCallV2(address indexed vault, address target, address fromAsset, uint fromAmount, address toAsset, address recipient, uint256 amountOutMin, string memo, bytes payload, string originAddress);

    // Emitted for failed transfers
    event TransferFailed(address indexed vault, address indexed to, address asset, uint amount, string memo);

    // Tracks balance changes between vaults using old router function
    event TransferAllowance(address indexed oldVault, address indexed newVault, address asset, uint amount, string memo);

    modifier nonReentrant() {
        require(_status != _ENTERED, "TC:reentrant");
        _status = _ENTERED;
        _;
        _status = _NOT_ENTERED;
    }

    //############################## DEPOSITS ##############################

    // User Deposit with Expiry 
    function depositWithExpiry(address payable vault, address asset, uint amount, string calldata memo, uint expiration) external payable nonReentrant {
        if(expiration != 0){ // Skip if setting 0 for no expiration
            require(block.timestamp < expiration, "TC:expired");
        }
        require(vault != address(this), "TC:vault!=router");
        _validateEthUsage(asset);
        uint safeAmount = _executeTransfer(vault, asset, amount);
        emit Deposit(vault, asset, safeAmount, memo);
    }

    //############################## TRANSFERS ##############################

    // Any vault calls to transfer any asset to any recipient.
    function transferOut(address payable to, address asset, uint amount, string calldata memo) external payable nonReentrant {
        _validateEthUsage(asset);
        _executeTransfer(to, asset, amount);
        emit TransferOut(msg.sender, to, asset, amount, memo);
    }

    // Batch transfer multiple assets in a single transaction
    function batchTransferOut(address payable[] calldata to, address[] calldata assets, uint[] calldata amounts, string[] calldata memos) external payable nonReentrant {
        require(
            to.length == assets.length && 
            to.length == amounts.length && 
            to.length == memos.length,
            "TC:length mismatch"
        );

        // Track total ETH needed for transfers
        uint256 ethRemaining = msg.value;

        // If the total ETH to transfer exceeds msg.value, the last one will be reduced
        for (uint i = 0; i < to.length;) {
            // If ETH transfer, track remaining ETH
            if (assets[i] == ETH_ASSET) {
                uint256 safeAmount = amounts[i] > ethRemaining ? ethRemaining : amounts[i];
                unchecked { ethRemaining -= safeAmount; }
                _sendEth(to[i], safeAmount);
                emit TransferOut(msg.sender, to[i], assets[i], safeAmount, memos[i]);
            } else {
                // For ERC20, just do the transfer
                _safeTransferFrom(assets[i], amounts[i], to[i]);
                emit TransferOut(msg.sender, to[i], assets[i], amounts[i], memos[i]);
            }
            unchecked {
                ++i;
            }
        }
        require(ethRemaining == 0, "TC:eth amount mismatch");
    }

    function _executeTransfer(address payable to, address asset, uint amount) internal returns (uint transferredAmount) {
        if (asset == ETH_ASSET) {
            // Handle ETH transfer
            require(msg.value == amount, "TC:eth amount mismatch");
            _sendEth(to, msg.value);
            transferredAmount = msg.value;
        } else {
            // Handle ERC20 transfer
            transferredAmount = _safeTransferFrom(asset, amount, to);
        }
        return transferredAmount;
    }

    //############################## AGGREGATION ##############################

    // Transfer and Call() with ETH
    function transferOutAndCall(address payable target, address finalToken, address to, uint256 amountOutMin, string calldata memo) external payable nonReentrant {
        (bool success, ) = target.call{value:msg.value}(abi.encodeWithSelector(SWAP_OUT_SIG, finalToken, to, amountOutMin));
        if (!success) {
            _sendEth(payable(to), msg.value); // If can't swap, just send to recipient
            emit TransferFailed(msg.sender, to, finalToken, msg.value, memo);
        }
        emit TransferOutAndCall(msg.sender, target, msg.value, finalToken, to, amountOutMin, memo);
    }

    // Transfer and Call() with ETH or ERC20
    function transferOutAndCallV2(Params calldata params) external payable nonReentrant {
        if (params.fromAsset == ETH_ASSET) {
            // Try to call, if fail, send ETH to recipient
            (bool success, ) = params.target.call{value:msg.value}(abi.encodeWithSelector(SWAP_OUT_V2_SIG, params.fromAsset, params.fromAmount, params.toAsset, params.recipient, params.amountOutMin, params.payload, params.originAddress));
            if (!success) {
                _sendEth(payable(params.recipient), msg.value); // If can't swap, just send to recipient
                emit TransferFailed(msg.sender, params.recipient, params.fromAsset, msg.value, params.memo);
            }
        } else {
            // Try to call, if fail, send tokens to recipient
            _validateEthUsage(params.fromAsset);
            uint safeAmount = _safeTransferFrom(params.fromAsset, params.fromAmount, address(this));
            _safeApprove(params.fromAsset, params.target, safeAmount);
            (bool success, ) = params.target.call(abi.encodeWithSelector(SWAP_OUT_V2_SIG, params.fromAsset, safeAmount, params.toAsset, params.recipient, params.amountOutMin, params.payload, params.originAddress));
            if (!success) {
                // If swap fails, zero out the approval
                _safeApprove(params.fromAsset, params.target, 0); 
                // Then send directly to recipient ignoring warnings
                // If we failed this, the Bifrost will infinite loop and use up gas
                params.fromAsset.call(abi.encodeWithSelector(TRANSFER_SIG, params.recipient, safeAmount));
                emit TransferFailed(msg.sender, params.recipient, params.fromAsset, params.fromAmount, params.memo);
            }
        }
        emit TransferOutAndCallV2(msg.sender, params.target, params.fromAsset, params.fromAmount, params.toAsset, params.recipient, params.amountOutMin, params.memo, params.payload, params.originAddress);
    }

    //##################### OLD ROUTER FUNCTIONS ######################

    // These two functions are backwards compatible with old router version
    // They are can be deprecated by a Bifrost upgrade

    // Get the token balance of a vault by wrapping the ERC20 method
    // Can be deprecated if Bifrost calls balanceOf directly on the vault
    function vaultAllowance(address vault, address token) external view returns(uint amount){
        return iERC20(token).balanceOf(vault);
    }

    // Use for churning ERC20s (not ETH) to a new vault, as well as router migrations
    // A router is needed to emit a txOut Memo at some point
    // Can be deprecated if Bifrost transfers assets directly to the new vault with no memo
    function transferAllowance(address router, address newVault, address asset, uint amount, string calldata memo) external nonReentrant {
        require(asset != ETH_ASSET, "TC:ETH unsupported");
        if (router == address(this)){
            // Retrieve asset from vault, send to new vault
            // TransferAllowance event is monitored by Bifrost
            _safeTransferFrom(asset, amount, payable(newVault));
            emit TransferAllowance(msg.sender, newVault, asset, amount, memo);
        } else {
            // Else transfer assets to new router/vault using deposit function to emit the memo
            // Bifrost will be monitoring the new router at this point to parse the deposit event (and memo)
            uint safeAmount = _safeTransferFrom(asset, amount, address(this)); // First get tokens from vault
            _safeApprove(asset, router, safeAmount); // Then approve new router
            iROUTER(router).depositWithExpiry(newVault, asset, safeAmount, memo, type(uint).max); // Transfer by depositing
        }
    }

    //############################## HELPERS ##############################

    // Safe transferFrom in case asset charges transfer fees
    function _safeTransferFrom(address _asset, uint _amount, address _to) internal returns(uint amount) {
        uint _startBal = iERC20(_asset).balanceOf(_to);
        (bool success, bytes memory data) = _asset.call(abi.encodeWithSelector(TRANSFER_FROM_SIG, msg.sender, _to, _amount));
        require(success && (data.length == 0 || abi.decode(data, (bool))), "TC:transfer failed");
        return (iERC20(_asset).balanceOf(_to) - _startBal);
    }

    // Safe approve for ERC20 tokens
    function _safeApprove(address _asset, address _spender, uint _amount) internal {
        (bool success, bytes memory data) = _asset.call(abi.encodeWithSelector(APPROVE_SIG, _spender, _amount));
        require(success && (data.length == 0 || abi.decode(data, (bool))), "TC:approve failed");
    }

    // Recipients of ETH are only given 2300 Gas to complete execution.
    function _sendEth(address payable to, uint256 amount) internal {
        bool success = to.send(amount);
        if (!success) {
            payable(msg.sender).transfer(amount); // If failure send back
            emit TransferFailed(msg.sender, to, ETH_ASSET, amount, "");
        }
    }

    // Helper function to validate ETH usage for ERC20 transfers
    function _validateEthUsage(address asset) internal view {
        if (asset != ETH_ASSET) {
            require(msg.value == 0, "TC:unexpected eth");
        }
    }
}

